// Aggregate all the parallel HTTP responses into a single metrics payload.
// Items from earlier nodes arrive via $items('Node Name').all

const success1h = $items('Executions (1h, success)').all.length;
const error1h = $items('Executions (1h, error)').all.length;
const total1h = success1h + error1h;
const total24h = $items('Executions (24h, all)').all.length;
const total7d = $items('Executions (7d, all)').all.length;

// Success rate per workflow (last 24h)
const execs24h = $items('Executions (24h, all)').all.map(i => i.json);
const byWorkflow = {};
for (const e of execs24h) {
  const wid = e.workflowId || (e.workflow?.id) || 'unknown';
  const wname = e.workflow?.name || wid;
  if (!byWorkflow[wid]) byWorkflow[wid] = { id: wid, name: wname, total: 0, success: 0, error: 0, durations: [] };
  byWorkflow[wid].total++;
  if (e.status === 'success' || e.finished === true) byWorkflow[wid].success++;
  if (e.status === 'error' || e.status === 'failed') byWorkflow[wid].error++;
  if (typeof e.runningTime === 'number') byWorkflow[wid].durations.push(e.runningTime);
}

const perWorkflow = Object.values(byWorkflow).map(w => ({
  workflow_id: w.id,
  workflow_name: w.name,
  total_24h: w.total,
  success_24h: w.success,
  error_24h: w.error,
  success_rate_24h: w.total ? (w.success / w.total) * 100 : 100,
  failure_rate_24h: w.total ? (w.error / w.total) * 100 : 0,
  avg_duration_ms_24h: w.durations.length ? Math.round(w.durations.reduce((a, b) => a + b, 0) / w.durations.length) : 0
}));

// Active workflows count
const workflows = $items('List Workflows').all.map(i => i.json).filter(w => w.active === true);

// Parse queue depth from /metrics (Prometheus text)
const metricsText = $items('n8n Prometheus Metrics').all[0]?.json?.data || $items('n8n Prometheus Metrics').all[0]?.json || '';
const queueMatch = (typeof metricsText === 'string' ? metricsText : JSON.stringify(metricsText)).match(/dayjoy_n8n_active_workflow_count\s+(\d+)/);
const queueDepthMatch = (typeof metricsText === 'string' ? metricsText : JSON.stringify(metricsText)).match(/dayjoy_n8n_active_workflow_count\s+(\d+)/);

const metrics = {
  collected_at: new Date().toISOString(),
  totals: {
    executions_1h: total1h,
    executions_success_1h: success1h,
    executions_error_1h: error1h,
    executions_24h: total24h,
    executions_7d: total7d,
    success_rate_1h_pct: total1h ? (success1h / total1h) * 100 : 100,
    failure_rate_1h_pct: total1h ? (error1h / total1h) * 100 : 0,
    active_workflows: workflows.length,
    queue_depth: queueDepthMatch ? parseInt(queueDepthMatch[1], 10) : 0
  },
  per_workflow: perWorkflow.sort((a, b) => b.total_24h - a.total_24h).slice(0, 50),
  instance: {
    host: process.env.N8N_HOST || 'n8n.dayjoy.ai',
    version: $items('n8n Prometheus Metrics').all[0]?.json?.version || 'unknown'
  }
};

return { json: metrics };

