=# HELP dayjoy_n8n_executions_1h Total n8n executions in the last hour
# TYPE dayjoy_n8n_executions_1h gauge
dayjoy_n8n_executions_1h {{ $json.totals.executions_1h }}
# HELP dayjoy_n8n_executions_24h Total n8n executions in the last 24 hours
# TYPE dayjoy_n8n_executions_24h gauge
dayjoy_n8n_executions_24h {{ $json.totals.executions_24h }}
# HELP dayjoy_n8n_executions_7d Total n8n executions in the last 7 days
# TYPE dayjoy_n8n_executions_7d gauge
dayjoy_n8n_executions_7d {{ $json.totals.executions_7d }}
# HELP dayjoy_n8n_success_rate_1h_pct Success rate (%) over last hour
# TYPE dayjoy_n8n_success_rate_1h_pct gauge
dayjoy_n8n_success_rate_1h_pct {{ $json.totals.success_rate_1h_pct }}
# HELP dayjoy_n8n_failure_rate_1h_pct Failure rate (%) over last hour
# TYPE dayjoy_n8n_failure_rate_1h_pct gauge
dayjoy_n8n_failure_rate_1h_pct {{ $json.totals.failure_rate_1h_pct }}
# HELP dayjoy_n8n_active_workflows Number of active (enabled) workflows
# TYPE dayjoy_n8n_active_workflows gauge
dayjoy_n8n_active_workflows {{ $json.totals.active_workflows }}
# HELP dayjoy_n8n_queue_depth Pending items in the n8n execution queue
# TYPE dayjoy_n8n_queue_depth gauge
dayjoy_n8n_queue_depth {{ $json.totals.queue_depth }}
{{ $json.per_workflow.map(w => `dayjoy_n8n_workflow_success_rate{workflow_id="${w.workflow_id}",workflow_name="${w.workflow_name.replace(/"/g, '\"')}"} ${w.success_rate_24h}
dayjoy_n8n_workflow_failure_rate{workflow_id="${w.workflow_id}",workflow_name="${w.workflow_name.replace(/"/g, '\"')}"} ${w.failure_rate_24h}
dayjoy_n8n_workflow_avg_duration_ms{workflow_id="${w.workflow_id}",workflow_name="${w.workflow_name.replace(/"/g, '\"')}"} ${w.avg_duration_ms_24h}
`).join('') }}
